"""Kitchen Sink page: DBGrid, a grid bound to a Data control: every pet of the Data page's
database, edited in place (AllowUpdate), a new one typed in its last row (AllowAddNew),
the selected rows deleted with Delete (AllowDelete); its rows follow the Data control."""

import os

from vp6 import *
from pgData import DATABASE, make_database


class pgDBGrid(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'DBGrid'
        self.Width = 640
        self.Height = 440
        self.grdPets = DBGrid(self, Left=16, Top=16, Width=608, Height=300,
                              Columns=['Name|Name|120', 'Kind|Kind|90', 'Age|Age|60|d', 'Notes|Notes|280'],
                              AllowAddNew=True, AllowDelete=True, TabIndex=1, DataSource='dtaPets')
        self.lblGrid = Label(self, Caption='Choose a cell; type to change it', Left=16, Top=324,
                             Width=440, Height=44, WordWrap=True, TabIndex=2)
        self.chkLocked = CheckBox(self, Caption='Refuse changes', Left=470, Top=324, Width=154,
                                  Height=25, TabIndex=3,
                                  ToolTipText='BeforeUpdate returns True: the change is cancelled')
        self.dtaPets = Data(self, Caption='Pets', Left=16, Top=384, Width=300, Height=33,
                            DatabaseName='pets.db',
                            RecordSource='SELECT * FROM pets ORDER BY Name')
        self.lblName = Label(self, Caption='Bound TextBox:', Left=332, Top=390, Width=110,
                             Height=22, TabIndex=4)
        self.txtName = TextBox(self, Text='', Left=444, Top=386, Width=180, Height=25, TabIndex=5,
                               DataSource='dtaPets', DataField='Name')
    # endregion

    def Form_Load(self):
        if not os.path.exists(DATABASE):  # (the Data page makes it, or this one)
            make_database(DATABASE)

    def grdPets_RowColChange(self):
        grid = self.grdPets
        column = grid.Columns(grid.Col).Caption if grid.Col >= 0 else ""
        self.lblGrid.Caption = f"RowColChange: row {grid.Row}, column {column}: {grid.Text!r}"

    def grdPets_BeforeUpdate(self):
        if self.chkLocked.Value == vpChecked:
            self.lblGrid.Caption = "BeforeUpdate: the change was refused"
            return True  # (cancels it)

    def grdPets_AfterUpdate(self):
        self.lblGrid.Caption = f"AfterUpdate: saved ({self.dtaPets.Recordset.RecordCount} pets)"

    def grdPets_BeforeDelete(self):
        return MsgBox("Delete the selected pets?", vpYesNo + vpQuestion) != vpYes


if __name__ == "__main__":
    run(pgDBGrid)
